import {memo, Suspense, useMemo} from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import BuildsFetcher from '../../../../../containers/BuildsFetcher'
import type {ChangeId} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import {getChange} from '../../Changes.selectors'
import ChangeBuilds from '../ChangeBuilds/ChangeBuilds'

import type {DeploymentsTabQuery} from './__generated__/DeploymentsTabQuery.graphql'

import {useAppSelector} from 'src/hooks/react-redux'

const query = graphql`
  query DeploymentsTabQuery($changeLocator: String!) {
    changeDeploymentConfigurations(changeLocator: $changeLocator) {
      ...ChangeBuilds_buildTypes
    }
  }
`

type Props = {
  buildTypesLocator: string
  buildsLocator: string
}

function DeploymentsTab({buildTypesLocator, buildsLocator}: Props) {
  const {changeDeploymentConfigurations = null} = useLazyLoadQuery<DeploymentsTabQuery>(query, {
    changeLocator: buildTypesLocator,
  })

  return (
    <ChangeBuilds
      buildsLocator={buildsLocator}
      isDeployment
      buildTypesKey={changeDeploymentConfigurations}
    />
  )
}

type ContainerProps = {
  changeId: ChangeId
}

const DeploymentsTabContainer = ({changeId}: ContainerProps) => {
  const personal = useAppSelector(state => getChange(state, changeId)?.personal)

  const buildTypesLocator = `id:${stringifyId(changeId)},personal:${personal || false}`
  const buildsLocator = `${buildTypesLocator},count:100000`

  return useMemo(
    () => (
      <BuildsFetcher
        locator={buildsLocator}
        customEndpoint={`/changes/${buildTypesLocator}/deployments`}
        withQueued
        withBuildDetails
      >
        <Suspense>
          <DeploymentsTab buildTypesLocator={buildTypesLocator} buildsLocator={buildsLocator} />
        </Suspense>
      </BuildsFetcher>
    ),
    [buildTypesLocator, buildsLocator],
  )
}

export default memo(DeploymentsTabContainer)
