import {HTMLHeading} from '@jetbrains/teamcity-ui/dist/components'
import plur from 'plur'
import {memo, useMemo} from 'react'

import {restApi} from '../../../../../../services/rest'
import type {ChangeId} from '../../../../../../types'
import {UserProperties} from '../../../../../../utils/userProperties'
import ContentPanel from '../../../../../common/ContentPanel/ContentPanel'
import {useSequenceLoaderReadyHandler} from '../../../../../common/SequenceLoader/SequenceLoader.hooks'
import type {SeqProps} from '../../../../../common/SequenceLoader/SequenceLoader.types'
import BuildProblemsTree from '../../../../BuildProblems/BuildProblemsTree/BuildProblemsTree.container'
import type {BuildProblemsTreeContextType} from '../../../../BuildProblems/BuildProblemsTree/BuildProblemsTree.context'
import {BuildProblemsTreeContext} from '../../../../BuildProblems/BuildProblemsTree/BuildProblemsTree.context'
import {useBuildProblemsTreeArg} from '../../../../BuildProblems/BuildProblemsTree/BuildProblemsTree.hooks'
import {getChange} from '../../../Changes.selectors'

import {getChangeProblemsTreeLocator} from './ChangeProblemsTree.utils'

import styles from './ChangeProblemsTree.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

type Props = SeqProps & {
  changeId: ChangeId
}

function ChangeProblemsTree({changeId}: Props) {
  const personal = useAppSelector(state => getChange(state, changeId)?.personal)

  const locator = getChangeProblemsTreeLocator(changeId, personal)
  const arg = useBuildProblemsTreeArg(locator)
  const {
    count = 0,
    newFailedCount = 0,
    isReady,
  } = restApi.endpoints.getProblemOccurrenceTree.useQuery(arg, {
    selectFromResult: ({data}) => {
      const {count, newFailedCount} = data?.tree.node?.find(node => node.name === '_Root') ?? {}
      return {count, newFailedCount, isReady: data != null}
    },
  })

  useSequenceLoaderReadyHandler(isReady && count === 0)

  const labelId = 'changeProblemsTree'
  const renderContent = useMemo(
    () => <BuildProblemsTree labelId={labelId} key={locator} locator={locator} />,
    [locator],
  )

  return isReady && count > 0 ? (
    <ContentPanel
      errorHeading
      panelType={UserProperties.EXPAND_CHANGE_PROBLEMS_SECTION}
      heading={
        count > 0 ? (
          <span id={labelId}>{`${count} Build ${plur('Problem', count)}${
            newFailedCount > 0 ? `, ${newFailedCount} new` : ''
          }`}</span>
        ) : (
          ''
        )
      }
      content={renderContent}
      withBorder={false}
    />
  ) : (
    <HTMLHeading className={styles.noProblemsHeading}>{'No build problems'}</HTMLHeading>
  )
}

function ChangeProblemsTreeWrapper(props: Props) {
  const buildProblemsTreeContextValue: BuildProblemsTreeContextType = useMemo(
    () => ({
      getEndpoint: treeLocator => `changes/${encodeURIComponent(treeLocator)}/problemsTree`,
      locatorInEndpoint: true,
    }),
    [],
  )

  return (
    <BuildProblemsTreeContext.Provider value={buildProblemsTreeContextValue}>
      <ChangeProblemsTree {...props} />
    </BuildProblemsTreeContext.Provider>
  )
}

export default memo(ChangeProblemsTreeWrapper)
