import Button from '@jetbrains/ring-ui-built/components/button/button'
import type {KeyValue} from '@jetbrains/teamcity-ui/dist/utils'
import {useCallback, useContext, useMemo, useState} from 'react'
import InfiniteScroll from 'react-infinite-scroll-component'

import type {BuildTypeId, NormalizedBuild} from '../../../../../types'
import {stringifyId} from '../../../../../types'
import {emptyArray} from '../../../../../utils/empty'

import {ChangeBuildsContext} from './ChangeBuilds.context'
import ChangeBuildsGrid from './ChangeBuildsGrid'
import ChangeBuildType from './ChangeBuildType/ChangeBuildType'
import ChangeBuildTypeDetails from './ChangeBuildTypeDetails/ChangeBuildTypeDetails'

import styles from './ChangeBuilds.module.css'

type Props = {
  buildTypeIds: ReadonlyArray<BuildTypeId>
  buildsHash: KeyValue<BuildTypeId, NormalizedBuild[]>
  isDeployment: boolean | undefined
}

function ChangeBuildsFlatList({buildTypeIds, buildsHash, isDeployment}: Props) {
  const {withInfiniteScroll, pageSize} = useContext(ChangeBuildsContext)

  const [currentPage, setCurrentPage] = useState<number>(1)
  const [showAll, setShowAll] = useState<boolean>(false)

  const truncatedBuildTypeIds = useMemo(
    () => (showAll ? buildTypeIds : buildTypeIds.slice(0, currentPage * pageSize)),
    [buildTypeIds, currentPage, pageSize, showAll],
  )

  const showMoreData = useCallback(() => {
    setCurrentPage(currentPage + 1)
  }, [currentPage])

  const showAllData = useCallback(() => {
    setShowAll(true)
  }, [])

  const hasMore = buildTypeIds.length !== truncatedBuildTypeIds.length

  const renderContent = useMemo(
    () => (
      <ChangeBuildsGrid>
        {truncatedBuildTypeIds.map(id => {
          const buildIds = buildsHash[id]?.map(build => build.id) ?? emptyArray
          return (
            <div className={styles.row} key={stringifyId(id)}>
              <ChangeBuildType buildIds={buildIds} buildTypeId={id} isDeployment={isDeployment} />
              <ChangeBuildTypeDetails buildIds={buildIds} />
            </div>
          )
        })}
      </ChangeBuildsGrid>
    ),
    [buildsHash, isDeployment, truncatedBuildTypeIds],
  )

  return (
    <div>
      {withInfiniteScroll ? (
        <InfiniteScroll
          className={styles.infiniteScroll}
          dataLength={truncatedBuildTypeIds.length}
          hasMore={hasMore}
          next={showMoreData}
          loader={<div className={styles.loader}>{'Loading...'}</div>}
        >
          {renderContent}
        </InfiniteScroll>
      ) : (
        <>
          {renderContent}
          {hasMore ? (
            <div className={styles.loadMoreButtonWrapper}>
              <Button onClick={showMoreData}>{'Load more'}</Button>
              {currentPage > 1 ? (
                <Button className={styles.showAllButton} onClick={showAllData} inline>
                  {'show all'}
                </Button>
              ) : null}
            </div>
          ) : null}
        </>
      )}
    </div>
  )
}

export default ChangeBuildsFlatList
